from collections import Counter

def get_pairs(tokens):
    return Counter(zip(tokens, tokens[1:]))

def train_bpe(text, num_merges):
    tokens = list(text)                    # start from characters
    merges = []
    for _ in range(num_merges):
        pairs = get_pairs(tokens)
        if not pairs: break
        best = max(pairs, key=pairs.get)   # most frequent adjacent pair
        merges.append(best)
        # merge every occurrence of `best` into a single token
        merged, i = [], 0
        while i < len(tokens):
            if i < len(tokens)-1 and (tokens[i], tokens[i+1]) == best:
                merged.append(tokens[i] + tokens[i+1]); i += 2
            else:
                merged.append(tokens[i]); i += 1
        tokens = merged
    return merges, tokens

merges, toks = train_bpe('low lower lowest ' * 20, num_merges=10)
print('learned merges:', merges[:5])   # ('l','o'), ('lo','w'), ... builds up 'low'
print('final token count:', len(toks), 'vs', len('low lower lowest ' * 20), 'chars')

